// Gate 13 · Metadata and previews
//
// Three things, and the second and third are new:
//
//   1. Every page carries a title, description, canonical and preview image,
//      and the preview image file exists. Plus the sitemap, robots.txt and the
//      Pagefind index.
//   2. **A preview image whose text is not from copy.yaml fails.** The images
//      are generated by scripts/og_render.mjs, which records each one's text
//      and where it came from in public/og/manifest.json. This re-resolves
//      every recorded source and fails if the recorded text no longer matches
//      it. That is what catches an image advertising a headline the site
//      stopped saying, which is exactly what default.png was doing (D-32).
//   3. **Any third-party origin in built output fails.** D-21: no analytics.
//      Trap 4: zero third-party requests. Only sub-resource loads count, so an
//      <a href> to GitHub is fine and a <script src> to a CDN is not.
//
// Usage:  node scripts/checks/meta_audit.mjs [dist]

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { DIST, ROOT, distPages, routeOf, readJson, parseCopy, leafStrings } from "./_lib.mjs";

const dist = process.argv[2] ?? DIST;
const pages = distPages(dist);
if (pages.length === 0) {
  console.error(`FAIL meta_audit: no built pages under ${dist}. Run npm run build first.`);
  process.exit(1);
}

let failures = 0;
const fail = (m) => {
  console.error(m);
  failures += 1;
};

// ---------------------------------------------------------------------------
// 1. Per page metadata
// ---------------------------------------------------------------------------

const REDIRECT = /<meta\s+http-equiv=["']refresh["']/i;
const referencedOg = new Set();
let redirectPages = 0;

for (const file of pages) {
  const route = routeOf(file, dist);
  const html = readFileSync(file, "utf-8");

  // A redirect stub is not a page. It carries noindex and a canonical to its
  // destination by construction, and asking it for a description would be
  // asking the wrong question of the right file.
  if (REDIRECT.test(html)) {
    redirectPages += 1;
    if (!/<link rel="canonical"/.test(html)) fail(`FAIL ${route}: redirect with no canonical link`);
    if (!/<meta name="robots" content="noindex"/.test(html)) {
      fail(`FAIL ${route}: redirect not marked noindex`);
    }
    continue;
  }

  const misses = [];
  if (!/<title>[^<]+<\/title>/.test(html)) misses.push("title");
  if (!/<meta name="description" content="[^"]+"/.test(html)) misses.push("description");
  if (!/<link rel="canonical" href="[^"]+"/.test(html)) misses.push("canonical");
  const og = html.match(/<meta property="og:image" content="([^"]+)"/);
  if (!og) misses.push("og:image");
  if (og) {
    const rel = og[1].replace(/^https?:\/\/[^/]+/, "");
    referencedOg.add(rel.replace(/^\//, ""));
    if (!existsSync(join(dist, rel))) misses.push(`og image file ${rel}`);
  }
  if (misses.length) fail(`FAIL ${route}: missing ${misses.join(", ")}`);
}

// ---------------------------------------------------------------------------
// 2. Preview image text resolves to its source
// ---------------------------------------------------------------------------

const manifest = readJson(join(ROOT, "public", "og", "manifest.json"));
if (!manifest) {
  fail(
    `FAIL public/og/manifest.json is missing. Run node scripts/og_render.mjs. Without it there is no way to know what text a preview image carries, which is how default.png advertised a rejected headline for months (D-32).`,
  );
} else {
  const copy = await parseCopy();
  const leaves = leafStrings(copy);
  const dataCache = new Map();

  const resolveSource = (source) => {
    // "design/copy.yaml:a.b + design/copy.yaml:c.d" or "a.b + c.d"
    if (source.startsWith("design/copy.yaml:")) {
      const keys = source.slice("design/copy.yaml:".length).split("+").map((s) => s.trim());
      const parts = keys.map((k) => leaves[k]);
      if (parts.some((p) => p === undefined)) return { ok: false, reason: `key not in copy.yaml: ${keys.join(", ")}` };
      return { ok: true, value: parts.join(" ") };
    }
    // "src/data/cards.json#<id>.title"
    const m = source.match(/^(.+?)#(.+)$/);
    if (m) {
      const [, path, accessor] = m;
      if (!dataCache.has(path)) dataCache.set(path, readJson(join(ROOT, path)));
      const doc = dataCache.get(path);
      if (!doc) return { ok: false, reason: `${path} does not exist` };
      const dot = accessor.lastIndexOf(".");
      const id = accessor.slice(0, dot);
      const field = accessor.slice(dot + 1);
      const row = Array.isArray(doc) ? doc.find((r) => r.id === id) : doc[id];
      if (!row) return { ok: false, reason: `no row ${id} in ${path}` };
      return { ok: true, value: row[field] };
    }
    return { ok: false, reason: `unrecognised source form` };
  };

  let checked = 0;
  for (const [file, entry] of Object.entries(manifest.images ?? {})) {
    const r = resolveSource(entry.source);
    if (!r.ok) {
      fail(`FAIL og/${file}: its recorded source does not resolve (${r.reason}). Source: ${entry.source}`);
      continue;
    }
    if (String(r.value).trim() !== String(entry.text).trim()) {
      fail(
        `FAIL og/${file}: the image carries text its source no longer says.\n` +
          `      image:  "${String(entry.text).slice(0, 90)}"\n` +
          `      source: "${String(r.value).slice(0, 90)}"  (${entry.source})\n` +
          `      Re-run: node scripts/og_render.mjs`,
      );
      continue;
    }
    checked += 1;
  }

  const unmanifested = [...referencedOg].filter((rel) => {
    const base = rel.replace(/^og\//, "");
    return rel.startsWith("og/") && !manifest.images?.[base];
  });
  for (const u of unmanifested) {
    fail(`FAIL a page references ${u}, which no generator produced and whose text nothing checks`);
  }

  console.log(`meta_audit: ${checked} preview image(s) whose text still matches its source`);
  const escalations = Object.entries(manifest.images ?? {}).filter(([, e]) => e.note);
  for (const [file, e] of escalations) console.warn(`WARN og/${file}: ${e.note}`);
}

// ---------------------------------------------------------------------------
// 3. Third-party origins in built output
// ---------------------------------------------------------------------------

const SUBRESOURCE = [
  /<script[^>]+src="(https?:\/\/[^"]+)"/gi,
  /<link[^>]+rel="(?:stylesheet|preload|prefetch|modulepreload|preconnect|dns-prefetch)"[^>]*href="(https?:\/\/[^"]+)"/gi,
  /<link[^>]+href="(https?:\/\/[^"]+)"[^>]*rel="(?:stylesheet|preload|prefetch|modulepreload|preconnect|dns-prefetch)"/gi,
  /<img[^>]+src="(https?:\/\/[^"]+)"/gi,
  /<iframe[^>]+src="(https?:\/\/[^"]+)"/gi,
  /<source[^>]+srcset="(https?:\/\/[^"]+)"/gi,
  /<video[^>]+(?:src|poster)="(https?:\/\/[^"]+)"/gi,
  /<object[^>]+data="(https?:\/\/[^"]+)"/gi,
  /url\((["']?)(https?:\/\/[^)"']+)\1\)/gi,
];
const OWN_ORIGIN = "reward-lens.github.io";

const thirdParty = new Map();
for (const file of pages) {
  const route = routeOf(file, dist);
  const html = readFileSync(file, "utf-8");
  for (const re of SUBRESOURCE) {
    for (const m of html.matchAll(re)) {
      const url = m[2] ?? m[1];
      if (!url?.startsWith("http")) continue;
      const host = new URL(url).host;
      if (host === OWN_ORIGIN) continue;
      if (host === "www.w3.org") continue; // SVG and XML namespace declarations
      if (!thirdParty.has(host)) thirdParty.set(host, new Set());
      thirdParty.get(host).add(route);
    }
  }
}
for (const [host, routes] of thirdParty) {
  fail(
    `FAIL third-party origin ${host} loaded as a sub-resource on ${routes.size} route(s): ${[...routes].slice(0, 4).join(", ")}. D-21: the site loads nothing from a third party.`,
  );
}

// ---------------------------------------------------------------------------
// 4. Site-level artifacts
// ---------------------------------------------------------------------------

if (!existsSync(join(dist, "sitemap-index.xml"))) fail("FAIL sitemap-index.xml missing");
const robots = join(dist, "robots.txt");
if (!existsSync(robots) || !readFileSync(robots, "utf-8").includes("Sitemap:")) {
  fail("FAIL robots.txt missing or lacks a Sitemap line");
}
if (!existsSync(join(dist, "pagefind", "pagefind.js"))) {
  fail("FAIL pagefind index missing (run pagefind after astro build)");
}

console.log(
  `meta_audit: ${pages.length} pages audited (${redirectPages} redirect stubs), ${thirdParty.size} third-party origins, ${failures} failures`,
);
process.exit(failures > 0 ? 1 : 0);
